  "message": "#12 [stage-0 5/5] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\nset -e\\nnode --version\\nyarn --version\\ncat \u003e qa328-probe.py \u003c\u003c'QA328_PYTHON_PROBE'\\nMARKER = \"QA328_a0808d_JS_TOOLS\"\\nimport json,os,platform,subprocess,sys\\nfrom pathlib import Path\\n\\ndef tool(name):\\n    try:\\n        r=subprocess.run([name,'--version'],text=True,capture_output=True,timeout=10)\\n        return {'status':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'error':None}\\n    except FileNotFoundError:\\n        return {'status':None,'stdout':'','stderr':'','error':'ENOENT'}\\n\\ndef snapshot():\\n    return {'marker':MARKER,'runtime':'python','version':platform.python_version(),'requested_python':os.environ.get('PYTHON_VERSION'),'tools':{name:tool(name) for name in ('node','npm','yarn','pnpm','python','pip')}}\\n\\nif '--build' in sys.argv:\\n    value=snapshot()\\n    Path('qa328-built.json').write_text(json.dumps(value,ensure_ascii=False))\\n    print(json.dumps(value,ensure_ascii=False),flush=True)\\nelse:\\n    from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer\\n    built=json.loads(Path('/opt/render/project/src/qa328-built.json').read_text())\\n    class Handler(BaseHTTPRequestHandler):\\n        def log_message(self,*args):pass\\n        def do_GET(self):\\n            value=snapshot();value['built']=built;body=json.dumps(value,ensure_ascii=False).encode()\\n            self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)\\n    ThreadingHTTPServer(('0.0.0.0',int(os.environ.get('PORT','3000'))),Handler).serve_forever()\\n\\nQA328_PYTHON_PROBE\\npython qa328-probe.py --build\"]",
